package parity

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"testing"

	"atf/worker/internal/domain/branding"
)

// reference_branding.json is generated by reference_branding.py, which runs
// the LIVE Python decision (core.domain.branding.should_hop and
// core.domain.services.SmartRoutingEngine.should_brand_hop) over every case
// and emits both the inputs and the decision it made. CI regenerates it and
// diffs, so a Python behavior change nobody re-referenced fails the build —
// exactly like the filter harness this package already ships.
//
//go:embed reference_branding.json
var brandingReferenceJSON []byte

// brandingFixture is one case of the shared fixture set.
type brandingFixture struct {
	Name    string         `json:"name"`
	Message map[string]any `json:"message"`
	Rule    map[string]any `json:"rule"`
	TakeHop bool           `json:"take_hop"`
	Reason  string         `json:"reason"`
}

// loadBrandingFixtures decodes the committed Python reference.
func loadBrandingFixtures(t *testing.T) []brandingFixture {
	t.Helper()
	var out []brandingFixture
	if err := json.Unmarshal(brandingReferenceJSON, &out); err != nil {
		t.Fatalf("decode branding reference: %v", err)
	}
	if len(out) == 0 {
		t.Fatal("branding reference is empty")
	}
	return out
}

// TestBrandingDecisionMatchesPython replays every shared fixture through the
// Go port and compares the decision to the one the LIVE Python
// implementation produced.
//
// The port is graded on the exact question Python was asked: the rule's
// metadata blob, its detection criteria and the message's forward origin are
// reconstructed from the same JSON, and the comparison is on the full
// (take_hop, reason) pair — a reason that drift is a decision that drifted,
// because the operator-facing panel shows that string.
func TestBrandingDecisionMatchesPython(t *testing.T) {
	for _, fx := range loadBrandingFixtures(t) {
		fx := fx
		t.Run(fx.Name, func(t *testing.T) {
			msg := brandingMessage(fx.Message)
			rule := brandingRule(fx.Rule)
			vipConfigured := branding.VIPConfigured(rule)
			vip := branding.VIPOf(msg, rule)
			got := branding.ShouldHop(msg, rule, vip, vipConfigured)
			if got.TakeHop != fx.TakeHop || got.Reason != fx.Reason {
				t.Errorf("decision drift:\n  got  take=%v reason=%q\n  want take=%v reason=%q",
					got.TakeHop, got.Reason, fx.TakeHop, fx.Reason)
			}
		})
	}
}

// TestBrandingFixturesAreComplete guards the fixture set itself: every case
// the Python reference knows must carry its inputs, or the Go harness would
// be comparing against an under-specified question.
func TestBrandingFixturesAreComplete(t *testing.T) {
	for _, fx := range loadBrandingFixtures(t) {
		if fx.Name == "" {
			t.Fatal("a fixture has no name")
		}
		// A case may legitimately leave C unconfigured (the disabled ones
		// exist to prove that guard), but every case must describe a rule
		// block and a message to be a well-formed question.
		if fx.Rule == nil {
			t.Errorf("fixture %s: rule block missing", fx.Name)
		}
		if fx.Message == nil {
			t.Errorf("fixture %s: message block missing", fx.Name)
		}
	}
}

// brandingMessage rebuilds the message-side input from the fixture's blob.
func brandingMessage(raw map[string]any) branding.MessageView {
	view := branding.MessageView{
		Text: strField(raw, "text"),
	}
	if origin, ok := raw["forward_origin"].(map[string]any); ok {
		view.ForwardOrigin = &branding.ForwardOrigin{
			FromChatID:       strField(origin, "from_chat_id"),
			FromChatUsername: strField(origin, "from_chat_username"),
			FromChatTitle:    strField(origin, "from_chat_title"),
		}
	}
	// Python's _text_of prefers effective_text, then text, then raw_text,
	// then caption. effective_text is itself derived (caption when the
	// message has media and a caption), so the fixture carries the derived
	// value only when the Python object would have produced one.
	if effective := strField(raw, "effective_text"); effective != "" {
		view.Text = effective
	}
	return view
}

// brandingRule rebuilds the task-side input from the fixture's blob.
func brandingRule(raw map[string]any) branding.RuleView {
	view := branding.RuleView{
		IntermediateChannelID: strField(raw, "intermediate_channel_id"),
		UseIntermediate:       boolField(raw, "use_intermediate"),
		IntermediateMode:      strField(raw, "intermediate_mode"),
		MessageCategory:       strField(raw, "message_category"),
	}
	if criteria, ok := raw["detection_criteria"].(map[string]any); ok {
		view.DetectionCriteria = criteria
	}
	if blob, ok := raw["branding_hop"].(map[string]any); ok {
		if view.Metadata == nil {
			view.Metadata = map[string]any{}
		}
		view.Metadata[branding.BrandingKey()] = blob
	}
	return view
}

// --- fixture field helpers ------------------------------------------------- //

func strField(m map[string]any, key string) string {
	if v, ok := m[key]; ok {
		if s, ok := v.(string); ok {
			return s
		}
	}
	return ""
}

func boolField(m map[string]any, key string) bool {
	if v, ok := m[key]; ok {
		switch b := v.(type) {
		case bool:
			return b
		case float64:
			return b != 0
		case string:
			return b == "1" || b == "true" || b == "yes" || b == "on"
		}
	}
	return false
}

var _ = fmt.Sprintf
